#!/usr/bin/env python3
"""Regenerate docs/avalonia-dashboard.html (self-contained, offline, inline SVG) from the port ledgers.

usage: port-dashboard.py [repo] [--flakes FILE] [--prs FILE.json] [--out FILE]
  parity status per area (last row per id wins), parity over time (one point per day from the ledger's git history,
  .md before the HTML move), main-sync progress per ledger, perf rows, known flakes (one test name per line,
  '#' comments) and open PRs (gh pr list --json number,title,isDraft,headRefName).
The port notes keep the output at ~/ccp-port/DASHBOARD.html (regenerated by the hourly audit), not in the repo.
Stdlib only; reads rows through avalonia_docs.py."""
import argparse
import collections
import html
import json
import os
import re
import subprocess
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import avalonia_docs as A  # noqa: E402

ORDER = ["missing", "blocked", "stub", "partial", "wired", "verified", "improved", "resolved", "n/a"]
COLOR = {"missing": "#d1242f", "blocked": "#8250df", "stub": "#bf8700", "partial": "#d4a72c", "wired": "#0969da",
         "verified": "#1a7f37", "improved": "#2da44e", "resolved": "#6e7781", "n/a": "#afb8c1",
         "ported-by-merge": "#1a7f37", "ported": "#2da44e", "folded": "#0969da", "needs-port": "#d1242f", "other": "#6e7781"}
AREAS = ["shell", "views", "win", "dialogs", "feat", "ctrl", "chaos", "theme"]


def git(repo, *a):
    return subprocess.run(["git", "-C", repo, *a], capture_output=True, text=True).stdout


def word(s):
    return re.split(r"[\s(]", s.strip().strip("`").lower() + " ")[0]


def parity_md(text):
    out = {}
    for l in text.split("\n"):
        c = [x.strip() for x in l.split("|")]
        if l.startswith("| ") and len(c) > 5 and c[1] not in ("id", "") and not set(c[1]) <= set("-"):
            out[c[1].strip("`")] = word(c[4])
    return out


def parity_html(text):
    return {r["id"].strip("`"): word(list(r.values())[3]) for r in A.rows(text, "id") if len(r) > 3}


def history(repo):
    seen, pts = {}, []
    for path in ("docs/avalonia-parity.html", "docs/avalonia-parity.md"):
        for line in git(repo, "log", "--format=%H %cs", "HEAD", "--", path).split("\n"):
            if line:
                sha, day = line.split()
                seen.setdefault(day, (sha, path))  # git log is newest first: the day's last commit
    for day in sorted(seen):
        sha, path = seen[day]
        t = git(repo, "show", f"{sha}:{path}")
        rows = parity_html(t) if path.endswith(".html") else parity_md(t)
        if rows:
            pts.append((day, collections.Counter(rows.values())))
    return pts


def bar(counts, keys, w=520):
    total = sum(counts.values()) or 1
    x, out = 0, []
    for k in keys:
        n = counts.get(k, 0)
        if not n:
            continue
        bw = n / total * w
        out.append(f'<rect x="{x:.1f}" y="0" width="{bw:.1f}" height="18" fill="{COLOR.get(k, "#6e7781")}">'
                   f'<title>{k}: {n}</title></rect>')
        x += bw
    return f'<svg class="bar" viewBox="0 0 {w} 18" width="{w}" height="18">{"".join(out)}</svg>'


def burn(pts, keys=("missing", "stub", "wired", "verified")):
    if not pts:
        return "<p>No history.</p>"
    W, H, P = 760, 220, 34
    top = max(max(c.get(k, 0) for k in keys) for _, c in pts) or 1
    sx = lambda i: P + i * (W - 2 * P) / max(1, len(pts) - 1)
    sy = lambda v: H - P - v * (H - 2 * P) / top
    lines, ly = [], {}
    for k in sorted(keys, key=lambda k: -sy(pts[-1][1].get(k, 0))):  # end labels bottom-up, at least 12px apart
        ly[k] = min(sy(pts[-1][1].get(k, 0)) + 4, min(ly.values(), default=H) - 12)
    for k in keys:
        d = " ".join(f"{'M' if i == 0 else 'L'}{sx(i):.1f},{sy(c.get(k, 0)):.1f}" for i, (_, c) in enumerate(pts))
        lines.append(f'<path class="ln" d="{d}" stroke="{COLOR[k]}"/><text x="{W - P + 4}" y="{ly[k]:.1f}" '
                     f'fill="{COLOR[k]}">{k} {pts[-1][1].get(k, 0)}</text>')
    ticks = "".join(f'<text x="{sx(i):.1f}" y="{H - 8}" text-anchor="middle">{d[5:]}</text>'
                    for i, (d, _) in enumerate(pts) if i % max(1, len(pts) // 8) == 0 or i == len(pts) - 1)
    axis = f'<line x1="{P}" y1="{H - P}" x2="{W - P}" y2="{H - P}"/><text x="4" y="{sy(top) + 4:.1f}">{top}</text>'
    return f'<svg class="chart" viewBox="0 0 {W + 80} {H}" width="{W + 80}" height="{H}">{axis}{ticks}{"".join(lines)}</svg>'


def legend(keys):
    return " ".join(f'<span class="lg"><i style="background:{COLOR.get(k, "#6e7781")}"></i>{k}</span>' for k in keys)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("repo", nargs="?", default=".")
    ap.add_argument("--flakes")
    ap.add_argument("--prs")
    ap.add_argument("--out")
    a = ap.parse_args()
    repo = os.path.abspath(a.repo)
    rd = lambda p: open(os.path.join(repo, p), encoding="utf-8").read()

    parity = parity_html(rd("docs/avalonia-parity.html"))
    total = collections.Counter(parity.values())
    by_area = collections.defaultdict(collections.Counter)
    for k, s in parity.items():
        p = k.split("-")[0]
        by_area[p if p in AREAS else "other"][s] += 1
    pts = history(repo)

    syncs = []
    for f in sorted(os.listdir(os.path.join(repo, "docs"))):
        if f.startswith("avalonia-main-sync-") and f.endswith(".html"):
            t = rd("docs/" + f)
            rows = [r for r in A.rows(t, "#") if re.fullmatch(r"`[0-9a-f]{7,12}`", r.get("sha", ""))]
            c = collections.Counter()
            for r in rows:
                s = r.get("status", "").lower()
                c["needs-port" if "needs-port" in s else "n/a" if s.startswith("n/a") else
                  "ported-by-merge" if "ported-by-merge" in s else "ported" if s.startswith("ported") else
                  "folded" if s.startswith("folded") else "partial" if s.startswith("partial") else "other"] += 1
            syncs.append((f[len("avalonia-main-sync-"):-5], c, A.meta(t)))

    perf = [r for t in A.tables(rd("docs/avalonia-perf.html")) if t["header"][:1] == ["metric"]
            for r in [dict(zip(t["header"], x)) for x in t["rows"]]]
    flakes = [l.strip() for l in open(a.flakes)] if a.flakes and os.path.exists(a.flakes) else None
    flakes = [l for l in flakes if l and not l.startswith("#")] if flakes is not None else None
    prs = json.load(open(a.prs)) if a.prs and os.path.exists(a.prs) else None

    e = html.escape
    open_rows = total.get("missing", 0) + total.get("stub", 0) + total.get("blocked", 0)
    s = [f'<h1>CCP Avalonia port dashboard</h1><p class="src">Generated {e(git(repo, "log", "-1", "--format=%cs %h").strip())} '
         f'by <code>.github/scripts/port-dashboard.py</code> from the ledgers. Hover a bar for its count.</p>',
         '<div class="cards">' + "".join(f'<div class="card"><b data-n="{n}">0</b><span>{k}</span></div>' for k, n in [
             ("parity rows", len(parity)), ("missing + stub + blocked", open_rows),
             ("wired", total.get("wired", 0)), ("verified + improved", total.get("verified", 0) + total.get("improved", 0)),
             ("needs-port (all syncs)", sum(c.get("needs-port", 0) for _, c, _ in syncs))]) + "</div>",
         "<h2>Parity by area</h2>", legend(ORDER), "<table><tr><th>area</th><th>rows</th><th>status</th>"
         + "".join(f"<th>{k}</th>" for k in ORDER) + "</tr>"]
    for area in AREAS + ["other"]:
        c = by_area.get(area)
        if c:
            s.append(f"<tr><td>{area}</td><td>{sum(c.values())}</td><td>{bar(c, ORDER, 300)}</td>"
                     + "".join(f"<td>{c.get(k, 0) or ''}</td>" for k in ORDER) + "</tr>")
    s.append(f"<tr><td><b>all</b></td><td><b>{len(parity)}</b></td><td>{bar(total, ORDER, 300)}</td>"
             + "".join(f"<td><b>{total.get(k, 0) or ''}</b></td>" for k in ORDER) + "</tr></table>")
    s += ["<h2>Parity over time</h2>", '<p class="src">Status counts per day (the last ledger commit of the day).</p>', burn(pts)]
    keys = ["ported-by-merge", "ported", "folded", "n/a", "partial", "needs-port", "other"]
    s += ["<h2>Main syncs</h2>", legend(keys), "<table><tr><th>ledger</th><th>rows</th><th>progress</th><th>needs-port</th><th>meta total</th></tr>"]
    for name, c, m in syncs:
        s.append(f"<tr><td>{e(name)}</td><td>{sum(c.values())}</td><td>{bar(c, keys)}</td><td>{c.get('needs-port', 0)}</td>"
                 f"<td>{(m or {}).get('total', '')}</td></tr>")
    s.append("</table>")
    s.append("<h2>Performance against WPF</h2>")
    if perf:
        h = list(perf[0])
        s.append("<table><tr>" + "".join(f"<th>{e(x)}</th>" for x in h) + "</tr>" + "".join(
            "<tr>" + "".join(f'<td class="{"gap" if x == "gap" else ""}">{e(r[x])}</td>' for x in h) + "</tr>" for r in perf) + "</table>")
    s.append("<h2>Tests and flakes</h2>")
    s.append(f"<p>{len(flakes)} known flaky test names: " + ", ".join(f"<code>{e(x)}</code>" for x in flakes) + "</p>"
             if flakes is not None else '<p class="src">No flake list given (--flakes).</p>')
    s.append("<h2>Open PRs</h2>")
    if prs is not None:
        n = collections.Counter("draft" if p.get("isDraft") else "ready" for p in prs)
        s.append(f"<p>{len(prs)} open: {n['ready']} ready, {n['draft']} draft.</p><details><summary>List</summary>")
        s.append("<table><tr><th>#</th><th>title</th><th>branch</th><th>state</th></tr>" + "".join(
            f'<tr><td>{p["number"]}</td><td>{e(p["title"])}</td><td><code>{e(p.get("headRefName", ""))}</code></td>'
            f'<td>{"draft" if p.get("isDraft") else "ready"}</td></tr>' for p in prs) + "</table></details>")
    else:
        s.append('<p class="src">No PR list given (--prs).</p>')

    css = """:root{color-scheme:light dark;--fg:#1f2328;--bg:#fff;--muted:#59636e;--line:#d1d9e0;--card:#f6f8fa}
@media (prefers-color-scheme:dark){:root{--fg:#e6edf3;--bg:#0d1117;--muted:#9198a1;--line:#3d444d;--card:#151b23}}
body{font:15px/1.5 system-ui,sans-serif;color:var(--fg);background:var(--bg);max-width:1200px;margin:2rem auto;padding:0 1.25rem}
h2{border-bottom:1px solid var(--line);padding-bottom:.3em;margin-top:1.8em}.src{color:var(--muted);font-size:.85em}
table{border-collapse:collapse;margin:.6em 0}th,td{border:1px solid var(--line);padding:.3em .55em;text-align:left;vertical-align:middle}
.cards{display:flex;gap:1em;flex-wrap:wrap}.card{background:var(--card);border-radius:8px;padding:.8em 1.2em;min-width:140px}
.card b{display:block;font-size:2em}.card span{color:var(--muted);font-size:.85em}
.lg{margin-right:1em;font-size:.85em}.lg i{display:inline-block;width:.8em;height:.8em;margin-right:.3em;border-radius:2px}
svg text{fill:var(--muted);font-size:11px}svg line{stroke:var(--line)}.ln{fill:none;stroke-width:2;stroke-dasharray:3000;
stroke-dashoffset:3000;animation:draw 1.6s ease-out forwards}.bar rect{transform-origin:left;animation:grow .8s ease-out}
@keyframes draw{to{stroke-dashoffset:0}}@keyframes grow{from{transform:scaleX(0)}}
@media (prefers-reduced-motion:reduce){.ln,.bar rect{animation:none;stroke-dashoffset:0}}td.gap{color:#d1242f}"""
    js = """for(const b of document.querySelectorAll('.card b')){const n=+b.dataset.n;const t0=performance.now();
const f=t=>{const p=Math.min(1,(t-t0)/700);b.textContent=Math.round(n*p);if(p<1)requestAnimationFrame(f)};
matchMedia('(prefers-reduced-motion: reduce)').matches?b.textContent=n:requestAnimationFrame(f);}"""
    data = {"parity": dict(total), "areas": {k: dict(v) for k, v in by_area.items()},
            "history": [[d, dict(c)] for d, c in pts], "syncs": {n: dict(c) for n, c, _ in syncs},
            "flakes": flakes, "open_prs": len(prs) if prs is not None else None}
    blob = json.dumps(data).replace("</", "<\\/")
    doc = ('<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n'
           f'<title>CCP Avalonia port dashboard</title>\n<style>\n{css}\n</style>\n'
           f'<script type="application/json" id="dashboard-data">{blob}</script>\n</head>\n<body>\n'
           + "\n".join(s) + f"\n<script>\n{js}\n</script>\n</body>\n</html>\n")
    out = a.out or os.path.join(repo, "docs/avalonia-dashboard.html")
    open(out, "w", encoding="utf-8").write(doc)
    print(out, f"{len(parity)} rows, {len(pts)} days, {len(syncs)} syncs")


if __name__ == "__main__":
    main()
